-- banking-microservices: consolidated database script (generated, do not edit by hand).
-- Source: the Flyway migrations of each service; regenerate with scripts/build-database-sql.sh.
--
-- With docker compose this script is NOT needed: each service creates its schema with
-- Flyway on startup. It documents the whole model and allows a manual setup:
--   psql -U postgres -f database.sql
-- One database and one user per service (database-per-service, ADR-011). The passwords
-- are the local development defaults; change them for any other environment.

CREATE ROLE clients_user LOGIN PASSWORD 'clients_pass';
CREATE DATABASE clients_db OWNER clients_user;
REVOKE ALL ON DATABASE clients_db FROM PUBLIC;

CREATE ROLE accounts_user LOGIN PASSWORD 'accounts_pass';
CREATE DATABASE accounts_db OWNER accounts_user;
REVOKE ALL ON DATABASE accounts_db FROM PUBLIC;

-- ============================================================================
-- clients-service
-- ============================================================================
\connect clients_db
SET ROLE clients_user;

-- clients-service/src/main/resources/db/migration/V1__create_person_and_client.sql
-- Person and Client with JOINED inheritance (ADR-006). SPEC §7.
CREATE TABLE person (
    id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name           VARCHAR(100) NOT NULL,
    gender         VARCHAR(10)  NOT NULL CONSTRAINT ck_person_gender CHECK (gender IN ('MALE', 'FEMALE', 'OTHER')),
    age            SMALLINT     NOT NULL CONSTRAINT ck_person_age CHECK (age BETWEEN 0 AND 120),
    identification VARCHAR(20)  NOT NULL CONSTRAINT uk_person_identification UNIQUE,
    address        VARCHAR(200) NOT NULL,
    phone          VARCHAR(16)  NOT NULL,
    -- Optimistic locking and event ordering (ADR-010). Hibernate requires it on the root table.
    version        BIGINT       NOT NULL
);

CREATE TABLE client (
    person_id BIGINT       PRIMARY KEY CONSTRAINT fk_client_person REFERENCES person (id) ON DELETE CASCADE,
    client_id UUID         NOT NULL CONSTRAINT uk_client_client_id UNIQUE,
    password  VARCHAR(100) NOT NULL,
    active    BOOLEAN      NOT NULL
);

-- clients-service/src/main/resources/db/migration/V2__create_outbox_event.sql
-- Transactional outbox (ADR-009). SPEC §7.
CREATE TABLE outbox_event (
    id           UUID        PRIMARY KEY,
    aggregate_id UUID        NOT NULL,
    type         VARCHAR(50) NOT NULL,
    payload      JSONB       NOT NULL,
    created_at   TIMESTAMPTZ NOT NULL,
    published_at TIMESTAMPTZ
);

-- Only pending rows are polled, in creation order.
CREATE INDEX ix_outbox_event_pending ON outbox_event (created_at) WHERE published_at IS NULL;

-- ============================================================================
-- accounts-service
-- ============================================================================
\connect accounts_db
SET ROLE accounts_user;

-- accounts-service/src/main/resources/db/migration/V1__create_accounts_schema.sql
-- accounts-service schema (SPEC §7).

-- Local replica of the clients of clients-service, fed by events (ADR-008).
CREATE TABLE client_snapshot (
    client_id      UUID         PRIMARY KEY,
    name           VARCHAR(100) NOT NULL,
    identification VARCHAR(20)  NOT NULL,
    active         BOOLEAN      NOT NULL,
    deleted        BOOLEAN      NOT NULL,
    version        BIGINT       NOT NULL,
    updated_at     TIMESTAMPTZ  NOT NULL
);

-- Ids of the client events already applied, for idempotent consumption (ADR-010).
CREATE TABLE processed_event (
    event_id     UUID        PRIMARY KEY,
    processed_at TIMESTAMPTZ NOT NULL
);

CREATE TABLE account (
    id                BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    account_number    VARCHAR(10)   NOT NULL CONSTRAINT uk_account_account_number UNIQUE,
    account_type      VARCHAR(10)   NOT NULL CONSTRAINT ck_account_type CHECK (account_type IN ('SAVINGS', 'CHECKING')),
    initial_balance   NUMERIC(15,2) NOT NULL CONSTRAINT ck_account_initial_balance CHECK (initial_balance >= 0),
    -- Last line of defense against a negative balance (ADR-013)
    available_balance NUMERIC(15,2) NOT NULL CONSTRAINT ck_account_available_balance CHECK (available_balance >= 0),
    active            BOOLEAN       NOT NULL,
    -- Local FK: the replica lives in this database, so it does not cross services
    client_id         UUID          NOT NULL CONSTRAINT fk_account_client REFERENCES client_snapshot (client_id),
    version           BIGINT        NOT NULL
);

CREATE INDEX ix_account_client_id ON account (client_id);

CREATE TABLE movement (
    id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    account_id    BIGINT        NOT NULL CONSTRAINT fk_movement_account REFERENCES account (id),
    movement_date TIMESTAMPTZ   NOT NULL,
    movement_type VARCHAR(10)   NOT NULL CONSTRAINT ck_movement_type CHECK (movement_type IN ('DEPOSIT', 'WITHDRAWAL')),
    amount        NUMERIC(15,2) NOT NULL CONSTRAINT ck_movement_amount CHECK (amount <> 0),
    balance       NUMERIC(15,2) NOT NULL CONSTRAINT ck_movement_balance CHECK (balance >= 0),
    -- The sign decides the type (ADR-012)
    CONSTRAINT ck_movement_type_matches_sign CHECK ((movement_type = 'DEPOSIT') = (amount > 0))
);

-- Statement by date range and latest movement of an account (F4, F2-AC8)
CREATE INDEX ix_movement_account_date ON movement (account_id, movement_date, id);

